-- ----------------------------
-- Table structure for bio_blocks
-- ----------------------------
DROP TABLE IF EXISTS `bio_blocks`;
CREATE TABLE `bio_blocks`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `bio_id` bigint UNSIGNED NOT NULL,
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `position` int NOT NULL DEFAULT 0,
  `data_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_blocks_bio`(`bio_id` ASC) USING BTREE,
  INDEX `idx_blocks_pos`(`bio_id` ASC, `position` ASC) USING BTREE,
  CONSTRAINT `fk_blocks_bio` FOREIGN KEY (`bio_id`) REFERENCES `bios` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 259 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

