-- ----------------------------
-- Table structure for bio_daily_views
-- ----------------------------
DROP TABLE IF EXISTS `bio_daily_views`;
CREATE TABLE `bio_daily_views`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `bio_id` int UNSIGNED NOT NULL,
  `view_date` date NOT NULL,
  `views` int UNSIGNED NOT NULL DEFAULT 0,
  `unique_views` int UNSIGNED NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uq_bio_day`(`bio_id` ASC, `view_date` ASC) USING BTREE,
  INDEX `idx_day`(`view_date` ASC) USING BTREE,
  INDEX `idx_bio`(`bio_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

