  `bio_id` int UNSIGNED NOT NULL,
  `view_date` date NOT NULL,
  `fp` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uq_fp`(`bio_id` ASC, `view_date` ASC, `fp` ASC) USING BTREE,
  INDEX `idx_bio_day`(`bio_id` ASC, `view_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

